package com.pretorianos.taskflow;
import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity {
 SQLiteDatabase db; LinearLayout root,list; TextView stats; int blue=0xff2549a0; String[] priorities={"Alta","Media","Baja"};
 @Override public void onCreate(Bundle b){super.onCreate(b);db=new SQLiteOpenHelper(this,"tasks.db",null,1){public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE tasks(id INTEGER PRIMARY KEY, title TEXT NOT NULL, category TEXT, due TEXT, priority TEXT, done INTEGER DEFAULT 0)");}public void onUpgrade(SQLiteDatabase d,int a,int b){}}.getWritableDatabase();root=column();root.setPadding(dp(20),dp(24),dp(20),dp(12));root.setBackgroundColor(0xfff1f4fa);setContentView(root);TextView h=label("TaskFlow",32);h.setTextColor(blue);root.addView(h);root.addView(label("Organiza tu día",16));stats=label("",18);root.addView(stats);Button add=button("+ Nueva tarea");root.addView(add);add.setOnClickListener(v->edit(-1,"","","","Media"));ScrollView scroll=new ScrollView(this);list=column();scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));refresh();}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);} LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;} TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xff172238);t.setPadding(0,dp(6),0,dp(6));return t;} Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}
 void refresh(){list.removeAllViews();int total=0,done=0;try(Cursor c=db.rawQuery("SELECT id,title,category,due,priority,done FROM tasks ORDER BY done, CASE priority WHEN 'Alta' THEN 0 WHEN 'Media' THEN 1 ELSE 2 END,due,id DESC",null)){while(c.moveToNext()){final long id=c.getLong(0);final String name=c.getString(1),cat=c.getString(2),due=c.getString(3),p=c.getString(4);boolean checked=c.getInt(5)==1;total++;if(checked)done++;LinearLayout card=column();card.setPadding(dp(12),dp(8),dp(12),dp(8));card.setBackgroundColor(Color.WHITE);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(10);list.addView(card,lp);CheckBox cb=new CheckBox(this);cb.setText(name);cb.setTextSize(19);cb.setChecked(checked);card.addView(cb);card.addView(label(cat+" · Prioridad "+p+"\nEntrega: "+(due.isEmpty()?"Sin fecha":due),14));cb.setOnCheckedChangeListener((v,b)->{ContentValues x=new ContentValues();x.put("done",b?1:0);db.update("tasks",x,"id=?",new String[]{""+id});refresh();});LinearLayout row=new LinearLayout(this);Button e=button("Editar"),del=button("Eliminar");row.addView(e,new LinearLayout.LayoutParams(0,-2,1));row.addView(del,new LinearLayout.LayoutParams(0,-2,1));card.addView(row);e.setOnClickListener(v->edit(id,name,cat,due,p));del.setOnClickListener(v->new AlertDialog.Builder(this).setMessage("¿Eliminar esta tarea?").setNegativeButton("Cancelar",null).setPositiveButton("Eliminar",(d,w)->{db.delete("tasks","id=?",new String[]{""+id});refresh();}).show());}}stats.setText(done+" de "+total+" completadas · "+(total==0?0:100*done/total)+"%\nPendientes: "+(total-done));if(total==0)list.addView(label("Todavía no tienes tareas. Crea una para comenzar.",16));}
 void edit(long id,String name,String cat,String due,String priority){LinearLayout form=column();form.setPadding(dp(20),dp(8),dp(20),0);EditText title=new EditText(this);title.setHint("Nombre de la tarea");title.setText(name);form.addView(title);EditText category=new EditText(this);category.setHint("Categoría (ej. Universidad)");category.setText(cat);form.addView(category);TextView date=label(due,16);Button pick=button("Seleccionar fecha de entrega");form.addView(pick);form.addView(date);pick.setOnClickListener(v->{Calendar now=Calendar.getInstance();new DatePickerDialog(this,(a,y,m,d)->date.setText(String.format(Locale.US,"%04d-%02d-%02d",y,m+1,d)),now.get(Calendar.YEAR),now.get(Calendar.MONTH),now.get(Calendar.DAY_OF_MONTH)).show();});form.addView(label("Prioridad",16));Spinner spin=new Spinner(this);spin.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,priorities));spin.setSelection(Arrays.asList(priorities).indexOf(priority));form.addView(spin);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(id<0?"Nueva tarea":"Editar tarea").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{String n=title.getText().toString().trim();if(n.isEmpty()){title.setError("Escribe un nombre");return;}ContentValues x=new ContentValues();x.put("title",n);x.put("category",category.getText().toString().trim().isEmpty()?"General":category.getText().toString().trim());x.put("due",date.getText().toString());x.put("priority",spin.getSelectedItem().toString());if(id<0)db.insertOrThrow("tasks",null,x);else db.update("tasks",x,"id=?",new String[]{""+id});dialog.dismiss();refresh();}));dialog.show();}
}
